    final Runnable syncChanges=()->refreshNative();
    final Runnable accessTick=new Runnable(){public void run(){if(destroyed||paused||!api.authenticated())return;work(()->{api.checkAccess(false);return true;},ok->{});long interval=live?120000:30000;if(System.currentTimeMillis()-lastRecovery>interval){lastRecovery=System.currentTimeMillis();refreshNative();}main.postDelayed(this,15000);}};
    interface Work<T>{T run()throws Exception;}
    interface Done<T>{void accept(T result)throws Exception;}
    @Override public void onCreate(Bundle b){super.onCreate(b);
        File cache=new File(getFilesDir(),"catalog-native.encrypted");
        api=new NativeApi(new NativeApi.Cache(){public String read()throws Exception{return new String(Files.readAllBytes(cache.toPath()),java.nio.charset.StandardCharsets.UTF_8);}public void write(String text)throws Exception{File tmp=new File(getFilesDir(),"catalog-native.tmp");Files.write(tmp.toPath(),Crypto.utf8(text));if(!tmp.renameTo(cache))throw new Exception("No se pudo conservar la caché cifrada.");}});
        root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(SOFT);
        if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets x=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(x.left,x.top,x.right,x.bottom);return insets;});}else root.setFitsSystemWindows(true);
        setContentView(root);loginView();
    }
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(5));v.setTextIsSelectable(true);return v;}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
    LinearLayout card(LinearLayout parent){LinearLayout c=column();c.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(14));bg.setStroke(dp(1),0xffd9e4dd);c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));parent.addView(c,lp);return c;}
    Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(GREEN);b.setOnClickListener(v->action.run());return b;}
    EditText input(String hint,boolean password){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setTextSize(16);e.setTextColor(INK);e.setInputType(password?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);e.setPadding(dp(10),dp(10),dp(10),dp(10));return e;}
    void notify(String s){if(!destroyed)Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    void error(Exception e){if(destroyed)return;String msg=e instanceof java.io.IOException?"No se pudo conectar. Revisa Internet y vuelve a intentarlo.":e.getMessage();new AlertDialog.Builder(this).setTitle("MegaControl").setMessage(msg==null?"No se pudo completar la operación.":msg).setPositiveButton("Aceptar",null).show();}
    void status(String s){if(stateText!=null)stateText.setText(s);}
    <T>void work(Work<T> job,Done<T> done){work(job,done,()->{});}
    <T>void work(Work<T> job,Done<T> done,Runnable finished){int view=viewEpoch,epoch=api.epoch;if(progress!=null)progress.setVisibility(View.VISIBLE);io.execute(()->{
        try{if(epoch!=api.epoch)throw new Exception("La sesión cambió.");T result=job.run();main.post(()->{if(destroyed)return;if(progress!=null)progress.setVisibility(View.GONE);try{if(epoch!=api.epoch||view!=viewEpoch)return;done.accept(result);}catch(Exception e){error(e);}finally{finished.run();}});}
        catch(Exception e){main.post(()->{if(destroyed)return;if(progress!=null)progress.setVisibility(View.GONE);try{if(!api.authenticated()&&screen!=-1){stopLive();loginView();error(e);}else if(view==viewEpoch)error(e);}finally{finished.run();}});}
    });}
    void loginView(){viewEpoch++;screen=-1;root.removeAllViews();LinearLayout c=column();c.setPadding(dp(26),dp(38),dp(26),dp(26));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(c);root.addView(scroll,new LinearLayout.LayoutParams(-1,-1));ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.megacontrol_logo);LinearLayout.LayoutParams logo=new LinearLayout.LayoutParams(dp(76),dp(76));c.addView(icon,logo);c.addView(text("MegaControl",30,GREEN));c.addView(text("Android · Control de salidas",16,MUTED));
        LinearLayout box=card(c);box.addView(text("Entra con tu cuenta",22,INK));box.addView(text("Usa el mismo usuario y contraseña de MegaControl.",15,MUTED));EditText user=input("Usuario",false),password=input("Contraseña",true);user.setAutofillHints(View.AUTOFILL_HINT_USERNAME);password.setAutofillHints(View.AUTOFILL_HINT_PASSWORD);box.addView(user);box.addView(password);progress=new ProgressBar(this);progress.setVisibility(View.GONE);box.addView(progress);stateText=text("Conectado al proyecto de MegaControl.",13,MUTED);box.addView(stateText);
        Button sign=button("Iniciar sesión",()->{});sign.setOnClickListener(v->{if(user.getText().toString().trim().isEmpty()||password.getText().length()==0){notify("Escribe tu usuario y contraseña.");return;}sign.setEnabled(false);char[] secret=password.getText().toString().toCharArray();password.setText("");String name=user.getText().toString();int attempt=viewEpoch;progress.setVisibility(View.VISIBLE);status("Verificando acceso cifrado…");
            io.execute(()->{try{api.login(name,secret);api.prepare(msg->main.post(()->{if(viewEpoch==attempt)status(msg);}));main.post(()->{if(!destroyed&&viewEpoch==attempt){shell();show(0);startLive();}});}catch(Exception e){Arrays.fill(secret,'\0');main.post(()->{if(!destroyed&&attempt==viewEpoch){sign.setEnabled(true);progress.setVisibility(View.GONE);status("Vuelve a intentar el acceso.");error(e);}});}});
        });box.addView(sign);c.addView(text("La información se descifra en el teléfono. La app no guarda tu contraseña.",13,MUTED));}
    void shell(){root.removeAllViews();header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(18),dp(8),dp(10),dp(8));header.setBackgroundColor(Color.WHITE);TextView name=text("MegaControl",23,GREEN);header.addView(name,new LinearLayout.LayoutParams(0,-2,1));header.addView(button("⋮",()->new AlertDialog.Builder(this).setTitle("@"+api.username+" · "+(api.role.equals("admin")?"Administrador":"Usuario")).setItems(new String[]{"Actualizar catálogo","Buscar actualización de la app","Cerrar sesión"},(d,n)->{if(n==0)work(()->api.prepare(null),s->{status(s);notify("Catálogo comprobado.");});else if(n==1)checkUpdate();else logout();}).show()));root.addView(header);stateText=text("@"+api.username,12,MUTED);stateText.setPadding(dp(18),0,dp(18),0);root.addView(stateText);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setVisibility(View.GONE);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));bottom=new LinearLayout(this);bottom.setPadding(dp(4),dp(2),dp(4),dp(2));bottom.setBackgroundColor(Color.WHITE);String[] labels={"Escanear","Archivo","Consultas","Chat"};for(int i=0;i<labels.length;i++){final int n=i;bottom.addView(button(labels[i],()->show(n)),new LinearLayout.LayoutParams(0,dp(58),1));}root.addView(bottom);}
    void show(int target){viewEpoch++;screen=target;content.removeAllViews();page=column();page.setPadding(dp(16),dp(10),dp(16),dp(20));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(page);content.addView(scroll);for(int i=0;i<bottom.getChildCount();i++)bottom.getChildAt(i).setBackgroundColor(i==target?0xffdceee3:Color.WHITE);status("@"+api.username+" · "+(api.role.equals("admin")?"Administrador":"Usuario"));if(target==0)scannerView();else if(target==1)archiveView();else if(target==2)queriesView();else chatView();}
    void scannerView(){page.addView(text("Consultar producto",25,INK));page.addView(text(api.summary(),13,MUTED));LinearLayout box=card(page);box.addView(button("▥  ESCANEAR PRODUCTO",()->startActivityForResult(new Intent(this,ScannerActivity.class),SCAN)));box.addView(button("Leer foto de una etiqueta",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"),PHOTO)));
        searchMode=new Spinner(this);searchMode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Código de barras","Referencia","Nombre o referencia parcial"}));box.addView(searchMode);codeInput=input("Escribe el código",false);codeInput.setImeOptions(EditorInfo.IME_ACTION_SEARCH);codeInput.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_SEARCH){lookup();return true;}return false;});box.addView(codeInput);box.addView(button("Buscar",()->lookup()));box.addView(text("Los ceros iniciales se conservan. EAN, UPC, Code 128, Code 39 e ITF.",12,MUTED));scanResult=column();page.addView(scanResult);}
    void lookup(){String raw=codeInput.getText().toString().trim();if(raw.isEmpty()){notify("Escribe el código, nombre o referencia.");return;}int mode=searchMode.getSelectedItemPosition();status("Consultando precio e índice…");if(mode==2){work(()->api.search(raw),matches->{scanResult.removeAllViews();scanResult.addView(text(matches.size()+" coincidencias",20,INK));for(NativeApi.Match m:matches){String code=NativeApi.text(m.product,"codigo"),ref=NativeApi.text(m.product,"ref");LinearLayout c=card(scanResult);c.addView(text(NativeApi.text(m.product,"descripcion"),18,INK));c.addView(text(code+" · "+ref,14,MUTED));c.addView(button("Consultar",()->{codeInput.setText(code.isEmpty()?ref:code);searchMode.setSelection(code.isEmpty()?1:0);lookup();}));}});}
        else work(()->api.lookup(raw,mode==1),r->{renderResult(r);recordQuery(r);});}
    void renderResult(NativeApi.Result r)throws Exception{lastResult=r;scanResult.removeAllViews();LinearLayout c=card(scanResult);boolean found=r.match!=null&&!r.ambiguous;c.addView(text(found?"Producto encontrado":r.ambiguous?"Referencia ambigua":r.incomplete?"Consulta incompleta":"Sin coincidencia en el índice",20,found?GREEN:0xff8a5b14));
        if(r.incomplete)c.addView(text("El índice está incompleto. Puede haber documentos más recientes pendientes de preparar.",14,0xff8a5b14));
        if(!found){c.addView(text(r.query,24,INK));c.addView(text(r.ambiguous?"Esta referencia pertenece a varios códigos. Consulta el código de la etiqueta.":r.incomplete?"No se puede confirmar la ausencia del producto con el índice incompleto.":"Este código no aparece en los documentos preparados. No confirma que falte en el inventario de la empresa.",16,MUTED));return;}
        JSONObject product=r.match.product,doc=r.match.doc;c.addView(text(NativeApi.text(product,"descripcion"),23,INK));Double original=NativeApi.value(product,"pventa");Long cents=r.override!=null?r.override.getLong("cents"):original==null||r.conflicting?null:Math.round(original*100);c.addView(text(cents==null?"Precio de venta no disponible":String.format(Locale.US,"USD %.2f",cents/100.0),35,GREEN));
        c.addView(text(r.override!=null?"Precio modificado por un administrador · "+when(r.override.getString("updated_at")):"registered".equals(doc.optString("kind"))?"Precio del registro administrativo":"Precio de la última factura encontrada",14,MUTED));if(r.conflicting&&r.override==null)c.addView(text("La misma factura contiene precios distintos. Revisa el documento.",14,0xff8a5b14));
        detail(c,"Código de barras",NativeApi.text(product,"codigo"));detail(c,"Referencia",NativeApi.text(product,"ref"));detail(c,"Empaque",NativeApi.text(product,"empaque"));detail(c,"Salida de origen",NativeApi.text(doc,"salida"));detail(c,"Fecha de factura",date(NativeApi.text(doc,"invoiceDate")));detail(c,"Precio comprobado",when(Instant.ofEpochMilli(r.checkedAt).toString()));
        if(api.role.equals("admin"))c.addView(button("Editar precio",()->editPrice(r,cents,null)));
        c.addView(button("Historial de precios",()->priceHistory(r,0)));
        if(!r.history.isEmpty()){c.addView(text("Salidas",20,INK));for(NativeApi.Match m:r.history){Double price=NativeApi.value(m.product,"pventa");c.addView(text("Salida "+NativeApi.text(m.doc,"salida")+" · "+(price==null?"Sin precio":String.format(Locale.US,"USD %.2f",price))+" · "+date(NativeApi.text(m.doc,"invoiceDate")),14,MUTED));}}
        c.addView(button("Compartir producto en el chat",()->share(r,cents)));status("Consulta comprobada · "+api.summary());
    }
    void detail(LinearLayout p,String label,String value){p.addView(text(label,12,MUTED));p.addView(text(value.isEmpty()?"No disponible en el documento":value,16,INK));}
    void editPrice(NativeApi.Result result,Long initial,Long restoredVersion){LinearLayout form=column();form.setPadding(dp(20),dp(6),dp(20),dp(6));EditText price=input("Nuevo precio de venta",false),reason=input("Motivo del cambio",false);price.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);if(initial!=null)price.setText(String.format(Locale.US,"%.2f",initial/100.0));form.addView(price);form.addView(reason);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(restoredVersion==null?"Editar precio":"Restaurar precio de versión "+restoredVersion).setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(v2->{try{String raw=price.getText().toString().trim().replace(',','.');if(!raw.matches("[0-9]{1,7}(\\.[0-9]{1,2})?"))throw new Exception("Escribe un precio válido, por ejemplo 7.99.");long cents=new BigDecimal(raw).movePointRight(2).longValueExact();String note=reason.getText().toString().trim();if(note.isEmpty())throw new Exception("Escribe el motivo del cambio.");long expected=result.override==null?0:result.override.getLong("version");Long previous=result.override!=null?result.override.getLong("cents"):NativeApi.value(result.match.product,"pventa")==null?null:Math.round(NativeApi.value(result.match.product,"pventa")*100);
                dialog.getButton(-1).setEnabled(false);work(()->{api.setPrice(result.lookupCode,cents,expected,note,previous,restoredVersion);return api.lookup(result.query,result.byReference);},r->{dialog.dismiss();renderResult(r);notify("Precio guardado y compartido con el equipo.");},()->{if(dialog.isShowing())dialog.getButton(-1).setEnabled(true);});
            }catch(Exception e){error(e);}}));dialog.show();}
    void priceHistory(NativeApi.Result r,int offset){work(()->{Map<String,String> names=api.authors();JSONArray rows=api.priceHistory(r.lookupCode,offset);return NativeApi.obj("rows",rows,"names",new JSONObject(names));},response->{LinearLayout items=column();items.setPadding(dp(16),dp(10),dp(16),dp(10));JSONArray rows=response.getJSONArray("rows");JSONObject names=response.getJSONObject("names");for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);LinearLayout c=card(items);c.addView(text(String.format(Locale.US,"USD %.2f",p.getLong("cents")/100.0)+" · Versión "+p.getLong("version"),20,GREEN));c.addView(text("@"+names.optString(p.getString("updated_by"),"Equipo")+" · "+when(p.getString("updated_at")),13,MUTED));c.addView(text(p.optString("reason","Sin motivo registrado"),15,INK));if(api.role.equals("admin")){long cents=p.getLong("cents"),version=p.getLong("version");c.addView(button("Restaurar este precio",()->editPrice(r,cents,version)));}}if(rows.length()==0)items.addView(text("No hay cambios administrativos registrados.",16,MUTED));if(rows.length()==20)items.addView(button("Ver cambios anteriores",()->priceHistory(r,offset+20)));showDialog("Historial de precios",items);});}
    void recordQuery(NativeApi.Result r){io.execute(()->{try{JSONObject ticket=api.queryTicket(r);File pending=new File(getFilesDir(),"query-pending-"+ticket.getString("id")+".json");Files.write(pending.toPath(),Crypto.utf8(ticket.toString()));api.saveQuery(ticket);pending.delete();}catch(Exception e){main.post(()->{if(!destroyed&&api.authenticated())status("Consulta pendiente de compartir. Reintenta desde Consultas.");});}});}
    void retryQueries(){work(()->{File[] files=getFilesDir().listFiles((d,name)->name.startsWith("query-pending-")&&name.endsWith(".json"));int count=0;if(files!=null)for(File f:files){JSONObject ticket=new JSONObject(new String(Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8));if(api.userId.equals(ticket.optString("owner"))){api.saveQuery(ticket);f.delete();count++;}}return count;},n->{notify(n+" consultas confirmadas.");show(2);});}
    void queriesView(){page.addView(text("Consultas compartidas",25,INK));page.addView(text("Historial del equipo · Fechas y horas de Panamá",14,MUTED));page.addView(button("Actualizar",()->show(2)));page.addView(button("Reintentar consultas pendientes",()->retryQueries()));work(()->NativeApi.obj("rows",api.queries(),"names",new JSONObject(api.authors())),response->{JSONArray rows=response.getJSONArray("rows");JSONObject names=response.getJSONObject("names");for(int i=0;i<rows.length();i++){JSONObject q=rows.getJSONObject(i);LinearLayout c=card(page);c.addView(text(q.getString("code"),20,INK));c.addView(text(q.getString("label"),16,GREEN));if(!q.optString("description").isEmpty())c.addView(text(q.getString("description"),16,INK));c.addView(text("@"+names.optString(q.getString("created_by"),"Equipo")+" · "+when(q.getString("created_at")),13,MUTED));}if(rows.length()==0)page.addView(text("Aún no hay consultas compartidas.",16,MUTED));});}
    void archiveView(){page.addView(text("Archivo de salidas",25,INK));EditText number=input("Número exacto de salida",false);number.setInputType(InputType.TYPE_CLASS_NUMBER);number.setText(exactArchive);page.addView(number);page.addView(button("Buscar",()->{exactArchive=number.getText().toString().trim();archiveOffset=0;show(1);}));work(()->api.archive(archiveOffset,exactArchive),rows->{for(int i=0;i<rows.length();i++){JSONObject m=rows.getJSONObject(i),record=m.getJSONObject("record");LinearLayout c=card(page);c.addView(text("Salida "+m.getString("salida_numero"),21,INK));c.addView(text("@"+m.getString("username")+" · "+when(record.getString("created_at")),14,MUTED));c.addView(text(m.getInt("row_count")+" productos · "+m.getDouble("total_units")+" unidades",15,MUTED));if(record.optInt("salida_version")>0)c.addView(text("Versión "+record.getInt("salida_version")+" · Actual",13,GREEN));c.addView(button("Abrir detalle",()->archiveDetail(m)));}if(rows.length()==0)page.addView(text("No se encontraron salidas.",16,MUTED));LinearLayout pages=new LinearLayout(this);Button previous=button("Anterior",()->{archiveOffset=Math.max(0,archiveOffset-25);show(1);});previous.setEnabled(archiveOffset>0);pages.addView(previous,new LinearLayout.LayoutParams(0,-2,1));Button next=button("Siguiente",()->{archiveOffset+=25;show(1);});next.setEnabled(rows.length()==25);pages.addView(next,new LinearLayout.LayoutParams(0,-2,1));page.addView(pages);});}
    void archiveDetail(JSONObject m){try{JSONObject record=m.getJSONObject("record");LinearLayout box=column();box.setPadding(dp(18),dp(8),dp(18),dp(14));detail(box,"Responsable","@"+m.getString("username"));detail(box,"Fecha de registro",when(record.getString("created_at")));JSONObject doc=api.catalog.get(record.getString("id"));detail(box,"Fecha de factura",doc==null?"":date(NativeApi.text(doc,"invoiceDate")));detail(box,"Productos",String.valueOf(m.getInt("row_count")));detail(box,"Unidades",String.valueOf(m.getDouble("total_units")));box.addView(button("Ver PDF",()->work(()->api.document(record,"pdf"),bytes->PdfView.open(this,bytes))));box.addView(button("Guardar PDF",()->work(()->api.document(record,"pdf"),bytes->save(bytes,m.getString("pdf_name"),"application/pdf"))));box.addView(button("Guardar Excel original",()->work(()->api.document(record,"excel"),bytes->save(bytes,m.getString("excel_name"),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))));if(doc!=null){box.addView(text("Productos de esta salida",20,INK));JSONArray products=doc.getJSONArray("products");for(int i=0;i<products.length();i++){JSONObject p=products.getJSONObject(i);box.addView(text(NativeApi.text(p,"codigo")+" · "+NativeApi.text(p,"descripcion"),14,INK));}}box.addView(button("Historial de versiones",()->versions(record)));showDialog("Salida "+m.getString("salida_numero"),box);}catch(Exception e){error(e);}}
    void versions(JSONObject record){String tag=record.optString("salida_identity_tag");if(!tag.matches("[a-f0-9]{64}")){notify("Esta salida no tiene versiones vinculadas.");return;}work(()->api.list("mega_audit_records","salida_identity_tag=eq."+tag+"&select=*&order=salida_version.desc&limit=100"),rows->{LinearLayout c=column();c.setPadding(dp(16),dp(8),dp(16),dp(8));for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),m=api.metadata(row);LinearLayout item=card(c);item.addView(text("Versión "+row.optInt("salida_version")+(row.isNull("duplicate_of")?" · Actual":" · Anterior"),20,GREEN));item.addView(text("@"+m.getString("username")+" · "+when(row.getString("created_at")),14,MUTED));item.addView(text(m.getInt("row_count")+" productos · "+m.getDouble("total_units")+" unidades",15,INK));item.addView(button("Guardar PDF de esta versión",()->work(()->api.document(row,"pdf"),data->save(data,m.getString("pdf_name"),"application/pdf"))));item.addView(button("Guardar Excel de esta versión",()->work(()->api.document(row,"excel"),data->save(data,m.getString("excel_name"),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))));}showDialog("Historial de versiones",c);});}
    void chatView(){page.addView(text("Chat del equipo",25,INK));page.addView(text("Mensajes cifrados · Misma cuenta y base de datos",14,MUTED));LinearLayout messages=column();page.addView(messages);EditText message=input("Escribe un mensaje…",false);message.setSingleLine(false);message.setMaxLines(5);page.addView(message);Button send=button("Enviar",()->{String value=message.getText().toString().trim();if(value.isEmpty())return;if(value.length()>4000){notify("El mensaje supera 4,000 caracteres.");return;}work(()->{if(pendingMessage==null||!value.equals(pendingMessageText)){pendingMessage=api.messageTicket(NativeApi.obj("version",1,"text",value),"text",null);pendingMessageText=value;}api.send(pendingMessage);pendingMessage=null;pendingMessageText="";return true;},ok->{message.setText("");show(3);});});page.addView(send);page.addView(button("Actualizar conversación",()->show(3)));chatMessages(messages,0);}
    void chatMessages(LinearLayout target,long before){work(()->NativeApi.obj("rows",api.messages(before),"names",new JSONObject(api.authors())),response->{JSONArray rows=response.getJSONArray("rows");JSONObject names=response.getJSONObject("names");if(rows.length()==40){long older=rows.getJSONObject(0).getLong("seq");Button more=button("Ver mensajes anteriores",()->{target.removeAllViews();chatMessages(target,older);});target.addView(more);}for(int i=0;i<rows.length();i++){JSONObject m=rows.getJSONObject(i),body=m.getJSONObject("body");LinearLayout c=card(target);c.addView(text("@"+names.optString(m.getString("created_by"),"Equipo")+" · "+when(m.getString("created_at")),13,MUTED));String kind=m.getString("kind");if(kind.equals("text")||kind.equals("image"))c.addView(text(body.optString("text"),17,INK));if(kind.equals("sticker"))c.addView(text(sticker(body.optString("sticker")),32,GREEN));if(body.has("product")){JSONObject p=body.getJSONObject("product");c.addView(text(p.optString("description",p.optString("code")),19,INK));c.addView(text(p.optString("code")+" · "+p.optString("salida"),14,MUTED));if(!p.isNull("cents"))c.addView(text(String.format(Locale.US,"USD %.2f",p.getLong("cents")/100.0)+" · Precio al compartir",20,GREEN));}if(kind.equals("image"))c.addView(button("Ver foto",()->work(()->api.chatImage(m),bytes->{ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));Arrays.fill(bytes,(byte)0);new AlertDialog.Builder(this).setTitle("Foto del producto").setView(image).setPositiveButton("Cerrar",null).show();})));}if(rows.length()==0)target.addView(text("No hay mensajes en esta página.",16,MUTED));});}
    String sticker(String code){switch(code){case"ok":return"👍 Confirmado";case"checking":return"🔎 Lo estoy revisando";case"thanks":return"🙌 ¡Gracias!";case"box":return"📦 En bodega";case"wait":return"⏳ Un momento";case"done":return"✅ Resuelto";default:return"Sticker";}}
    void share(NativeApi.Result r,Long cents){try{JSONObject p=NativeApi.obj("version",1,"code",r.query,"identifier","barcode","result",r.match==null?"missing":"found","description",r.match==null?"":NativeApi.text(r.match.product,"descripcion"),"ref",r.match==null?"":NativeApi.text(r.match.product,"ref"),"salida",r.match==null?"":NativeApi.text(r.match.doc,"salida"),"source",r.override==null?"Factura":"Administrador","cents",cents,"checkedAt",Instant.ofEpochMilli(r.checkedAt).toString(),"invoiceDate",r.match==null?"":NativeApi.text(r.match.doc,"invoiceDate"),"sourceCode",r.lookupCode);new AlertDialog.Builder(this).setTitle("Compartir producto").setMessage(p.optString("description")+"\n"+p.optString("code")).setNegativeButton("Cancelar",null).setPositiveButton("Compartir",(d,n)->work(()->{JSONObject ticket=api.messageTicket(NativeApi.obj("version",1,"product",p),"product",null);api.send(ticket);return true;},ok->notify("Producto compartido en el chat."))).show();}catch(Exception e){error(e);}}
    void save(byte[] data,String name,String mime){if(pendingDownload!=null){Arrays.fill(data,(byte)0);notify("Termina el guardado anterior.");return;}pendingDownload=data;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[\\\\/\\p{Cntrl}]","_")),SAVE);}catch(Exception e){Arrays.fill(data,(byte)0);pendingDownload=null;error(e);}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==14){if(getPackageManager().canRequestPackageInstalls())Updater.install(this);return;}if(request==SCAN&&result==RESULT_OK&&data!=null){if(screen!=0)show(0);codeInput.setText(data.getStringExtra("code"));searchMode.setSelection(0);lookup();}else if(request==PHOTO&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();work(()->{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,options);}if((long)options.outWidth*options.outHeight>60000000)throw new Exception("La foto es demasiado grande. Recorta la etiqueta.");options.inSampleSize=Math.max(1,Math.max(options.outWidth,options.outHeight)/2400);options.inJustDecodeBounds=false;Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(in,null,options);}if(bitmap==null)throw new Exception("No se pudo leer la foto.");try{int w=bitmap.getWidth(),h=bitmap.getHeight();int[] pixels=new int[w*h];bitmap.getPixels(pixels,0,w,0,0,w,h);RGBLuminanceSource image=new RGBLuminanceSource(w,h,pixels);MultiFormatReader reader=new MultiFormatReader();Map<com.google.zxing.DecodeHintType,Object> hints=new java.util.EnumMap<>(com.google.zxing.DecodeHintType.class);hints.put(com.google.zxing.DecodeHintType.TRY_HARDER,true);try{return reader.decode(new BinaryBitmap(new HybridBinarizer(image)),hints).getText();}catch(Exception e){try{return reader.decode(new BinaryBitmap(new HybridBinarizer(image.invert())),hints).getText();}catch(Exception none){throw new Exception("No se distinguieron las barras. Prueba una foto más cercana o escribe el código.");}}}finally{bitmap.recycle();}},code->{if(screen!=0)show(0);codeInput.setText(code);searchMode.setSelection(0);lookup();});}else if(request==SAVE&&pendingDownload!=null){byte[] bytes=pendingDownload;pendingDownload=null;if(result!=RESULT_OK||data==null||data.getData()==null){Arrays.fill(bytes,(byte)0);notify("Guardado cancelado. Los originales se conservan en el Archivo.");return;}Uri destination=data.getData();work(()->{try(OutputStream out=getContentResolver().openOutputStream(destination,"wt")){if(out==null)throw new Exception("No se pudo abrir el destino.");out.write(bytes);out.flush();}finally{Arrays.fill(bytes,(byte)0);}return true;},ok->notify("Archivo guardado correctamente."));}}
    void showDialog(String title,View body){ScrollView scroll=new ScrollView(this);scroll.addView(body);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(scroll).setPositiveButton("Cerrar",null).create();dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(-1,-1);}
    String when(String value){try{return DateTimeFormatter.ofPattern("dd/MM/yyyy, h:mm a",new Locale("es","PA")).withZone(ZoneId.of("America/Panama")).format(Instant.parse(value));}catch(Exception e){return value;}}
    String date(String value){return value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")?value.substring(8,10)+"/"+value.substring(5,7)+"/"+value.substring(0,4):value.isEmpty()?"No confirmada en el documento":value;}
    void checkUpdate(){Updater.check(this,io,main);}
    void startLive(){if(destroyed||paused||!api.authenticated()||realtime!=null)return;int e=api.epoch;realtime=new Realtime(api.url,api.publicKey,api.workspace,()->io.submit(()->{if(e!=api.epoch)throw new Exception("La sesión cambió.");return api.realtimeToken();}).get(20,java.util.concurrent.TimeUnit.SECONDS),new Realtime.Events(){public void changed(String table){main.post(()->{if(destroyed||paused||e!=api.epoch)return;if(table.equals("all")||table.equals("mega_audit_records")||table.equals("mega_chat_products"))api.catalogChecked=0;main.removeCallbacks(syncChanges);main.postDelayed(syncChanges,500);});}public void status(boolean connected){main.post(()->{if(e==api.epoch&&!destroyed){live=connected;MainActivity.this.status(connected?"● En tiempo real · @"+api.username:"Reconectando · Comprobaciones de respaldo activas");}});}});main.removeCallbacks(accessTick);main.postDelayed(accessTick,15000);}
    void stopLive(){if(realtime!=null){realtime.close();realtime=null;}live=false;main.removeCallbacks(accessTick);main.removeCallbacks(syncChanges);}
    void refreshNative(){if(destroyed||paused||!api.authenticated())return;if(screen==0)work(()->{String summary=api.prepare(null);NativeApi.Result r=lastResult;if(r!=null)return api.lookup(r.query,r.byReference);return null;},r->{if(r!=null)renderResult(r);else status(api.summary());});else if(screen==2)show(2);else status("Hay cambios del equipo. Actualiza esta sección para verlos.");}
    void logout(){stopLive();api.clear();lastResult=null;pendingMessage=null;pendingMessageText="";if(pendingDownload!=null){Arrays.fill(pendingDownload,(byte)0);pendingDownload=null;}loginView();}
    @Override public void onBackPressed(){if(screen>0)show(0);else super.onBackPressed();}
    @Override protected void onPause(){paused=true;stopLive();super.onPause();}
    @Override protected void onResume(){super.onResume();paused=false;if(api!=null&&api.authenticated()&&screen>=0)work(()->{api.checkAccess(false);return true;},ok->startLive());}
    @Override protected void onDestroy(){destroyed=true;stopLive();api.clear();if(pendingDownload!=null)Arrays.fill(pendingDownload,(byte)0);io.shutdown();super.onDestroy();}
